public class NDXBVEMailRequestControlCenter extends FormRun implements NDXFormHandlerIncludedI
{
    int colorYellow = WinAPI::RGB2int(255, 248, 65);
    int colorGreen = WinAPI::RGB2int(137, 255, 186);
    int colorOrange = WinAPI::RGB2int(255, 188, 20);
    int colorLightBlue = WinAPI::RGB2int(183, 255, 243);
    int delayTimeOutMethod;
    int timeOutRuns;
    Counter emailRequestsStart;
    NDXBVEMailRequestControlCenterForm formhandler;
    NDXBVSearchContract bvSearchContract;
    boolean runActive;

}

/// <summary>
/// PaffH 25.07.25
/// last modified: PaffH 13.11.25
/// </summary>
public void init()
{
    delayTimeOutMethod = 5000;
    timeOutRuns = 0;
    emailRequestsStart = NDXBVEMailRequestHeader::countRecords();
    runActive = false;
    super();

    formhandler = NDXBVEMailRequestControlCenterForm::NewFromForm(element);
    bvSearchContract = new NDXBVSearchContract();
    formhandler.parmBVSearchContract(bvSearchContract);

    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1);
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1b);
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1c, "@NDX:NDXDataViaOutlookPlugin");
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1d, "@NDX:NDXDataViaOutlookPlugin");
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1e);
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1f);
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1g);
    this.initControlLocalizationOutlookPlugin(FormStaticTextInfo1h);

    this.initControlManualAssignment(FormStaticTextInfo2);
    this.initControlManualAssignment(FormStaticTextInfo2b);
    this.initControlManualAssignment(FormStaticTextInfo2c);
    this.initControlManualAssignment(FormStaticTextInfo2d);
    this.initControlManualAssignment(FormStaticTextInfo2e);
    this.initControlManualAssignment(FormStaticTextInfo2f);
    this.initControlManualAssignment(FormStaticTextInfo2g);

    this.initControlColor3(FormStaticTextInfo3b, "@NDX:NDXLocalizedContact");
    this.initControlColor3(FormStaticTextInfo3c, "@NDX:NDXLocalizedBuildingProject");
    this.initControlColor3(FormStaticTextInfo3d, "@NDX:NDXLocalizedPlaner");
    this.initControlColor3(FormStaticTextInfo3e, "@NDX:NDXLocalizedPlumber");
    this.initControlColor3(FormStaticTextInfo3f, "@NDX:NDXLocalizedRequest");
    this.initControlColor3(FormStaticTextInfo3g, "@NDX:NDXAssignedVialItemSuggestions");

    this.initControlStatistics(FormStaticTextInfo4a);
}

/// <summary>
/// PaffH 16.08.25
/// </summary>
/// <param name = "_formControl">FormStaticTextControl</param>
/// <param name = "_text">str</param>
private void initControlLocalizationOutlookPlugin(FormStaticTextControl _formControl, str _text = "@NDX:NDXLocalizationOutlookPlugin")
{
    NDXControlAttributes nDXControlAttributes = NDXControlAttributes::constructFromFormStaticTextControl(_formControl);
    nDXControlAttributes.parmColorScheme(FormColorScheme::RGB);
    nDXControlAttributes.parmBackgroundColor(colorYellow);
    nDXControlAttributes.parmText(_text);
}

