/// <summary>
/// PaffH 13.11.25
/// </summary>
/// <param name = "_formControl">FormStaticTextControl</param>
/// <param name = "_text">str</param>
private void initControlStatistics(FormStaticTextControl _formControl, str _text = "@NDXBase:NDXStatistic")
{
    NDXControlAttributes nDXControlAttributes = NDXControlAttributes::constructFromFormStaticTextControl(_formControl);
