/// <summary>
/// PaffH 16.08.25
/// last modified: PaffH 13.11.25
/// </summary>
public void run()
{
    runActive = true;
    super();
    runActive = false;
    element.setTimeoutEx(formMethodStr(NDXBVEMailRequestControlCenter, onTimeOut), conNull(), delayTimeOutMethod);
    formhandler.updateStatistiks();
}

/// <summary>
/// PaffH 06.09.25
/// new email request since start
/// </summary>
/// <param name = "_result"></param>
public void onTimeOut(AsyncTaskResult _result)
{
    if (element.closed())
    {
        return;
    }
    ++timeOutRuns;
    Counter emailRequestsDiff = NDXBVEMailRequestHeader::countRecords() - emailRequestsStart;
    HtmlViewerControl htmlControl = element.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, HtmlViewerRefreshInfo));
    str rgbBackGroundColor = emailRequestsDiff ? 'rgb(255, 117, 131)' : 'rgb(224, 255, 219)';
    str html = '<html><head><body>';
    html += '<h1 style="text-align: center;background-color:%1;border:2px solid DodgerBlue;">%2</h1>';
    html += '</body></head></html>';
    htmlControl.parmHtml(strFmt(html, rgbBackGroundColor, emailRequestsDiff));
    element.setTimeoutEx(formMethodStr(NDXBVEMailRequestControlCenter, onTimeOut), conNull(), delayTimeOutMethod);
}

