    ////////SysQuery::findOrCreateRange(qbds, fieldNum(smmBusRelTable, DataAreaId)).value(queryValue(companyFilter));
    //////SysQuery::findOrCreateRange(qbds, fieldNum(smmBusRelTable, BusRelAccount)).value(queryValue(NDXBVEMailRequestState.smmBusRelAccountManualSelected));
    //////smmBusRelTableState2_ds.executeQuery();
    //////RecId partyRecId = smmBusRelTableState2.Party;
    //info(strFmt("smmBusRelTableState2 UK [%1] Account [%2]", smmBusRelTableState2.DataAreaId, smmBusRelTableState2.BusRelAccount));

    //////q = DirPartyTable_ds.query();
    //////qbds = q.dataSourceName(DirPartyTable_ds.name());
    //////SysQuery::findOrCreateRange(qbds, fieldNum(DirPartyTable, RecId)).value(queryValue(partyRecId));
    //////DirPartyTable_ds.executeQuery();
    //info(strFmt("smmBusRelTableState2 UK [%1] Account [%2]", smmBusRelTableState2.DataAreaId, smmBusRelTableState2.BusRelAccount));

    q = CustTableState_ds.query();
    q.allowCrossCompany(true);
    q.clearCompanyRange();
    q.addCompanyRange(companyFilter);
    qbds = q.dataSourceName(CustTableState_ds.name());
    //SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, DataAreaId)).value(queryValue(companyFilter));
    SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(queryValue(NDXBVEMailRequestState.CustAccountManualSelected));
