/// <summary>
/// PaffH 22.09.25
/// </summary>
protected void positionDirPartyTablePlanerLookup()
{
    FormButtonControl control = element.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, FormButtonDeleteAssignedAddressPlaner));
    control.enabled(NDXBVEMailRequestPlaner.DirPartyTableManual);

    RecId recIdSelect = -1;
    if (NDXBVEMailRequestPlaner)
    {
        recIdSelect = NDXBVEMailRequestPlaner.DirPartyTableManual;
        if (!recIdSelect)
        {
            if (NDXBVEMailRequestPlaner.ProspectProspectId)
            {
                recIdSelect = DirPartyTable::find(NDXBVEMailRequestPlaner.ProspectProspectId).RecId;
            }
        }
        if (!recIdSelect)
        {
            recIdSelect = DirPartyTable::NDXfindOrCreateByNameEmpty().RecId;
        }
    }

    QueryBuildRange qbr = SysQuery::findOrCreateRange(DirPartyTablePlanerLookup_3_ds.QueryBuildDatasource(), fieldNum(DirPartyTable, RecId));
    qbr.value(queryValue(recIdSelect));
    DirPartyTablePlanerLookup_3_ds.executeQuery();
}

