/// <summary>
/// PaffH 14.08.25
/// last modified: PaffH 16.08.25
/// </summary>
public void executeQuery()
{
    //System.DateTime currentDate = System.DateTime::Now;
    //NDXQueryValue qValue = NDXHelperQuery::QueryInfo(ContactPersonLookup_q);
    super();
    //System.DateTime elapseDate = System.DateTime::Now;
    //int64 elapsedTicks = elapseDate.Ticks - currentDate.Ticks;
    //System.TimeSpan elapsedSpan = new System.TimeSpan(elapsedTicks);

    if (runActive)
    {
        runActive = false;
        //var nDXBVEMailRequestState_ContactPersonIdManualSelected = nDXBVEMailRequestState.ContactPersonIdManualSelected;
        //var ContactPersonLookup_ContactPersonId = ContactPersonLookup.ContactPersonId;
        //var NDXBVEMailRequestHeader_ContactPersonContactPersonId = NDXBVEMailRequestHeader.ContactPersonContactPersonId;
        if ((nDXBVEMailRequestState.ContactPersonIdManualSelected && nDXBVEMailRequestState.ContactPersonIdManualSelected != ContactPersonLookup.ContactPersonId) ||
            (NDXBVEMailRequestHeader.ContactPersonContactPersonId != ContactPersonLookup.ContactPersonId))
        {
            Query q = ContactPersonLookup_ds.query();
            q.clearCompanyRange();
            q.addCompanyRange(formhandler.getCompanyFilter());

            QueryBuildRange range = SysQuery::findOrCreateRange(ContactPersonLookup_ds.queryBuildDataSource(), fieldNum(ContactPerson, ContactPersonId));
            if (nDXBVEMailRequestState.ContactPersonIdManualSelected)
            {
                range.value(nDXBVEMailRequestState.ContactPersonIdManualSelected);
            }
            else
            {
                range.value(NDXBVEMailRequestHeader.ContactPersonContactPersonId);
            }
            ContactPersonLookup_ds.executeQuery();
            //DataAreaId uk = ContactPersonLookup.DataAreaId;
            //ContactPersonId id = ContactPersonLookup.ContactPersonId;
            //ContactPersonLookup_ds.reread();
            //ContactPersonLookup_ds.refresh();
        }
    }
    formhandler.checkContactPersonLookup();
}

